-- Plantilla que monta la aplicación (pega el texto del usuario entre comillas)
SELECT * FROM users WHERE username = '[usuario]' AND password = '[contraseña]';

-- Lo que escribe el atacante en el campo «usuario»:
admin' OR '1'='1

-- Consulta que llega a la base de datos:
SELECT * FROM users WHERE username = 'admin' OR '1'='1' AND password = '';
